package com.fakelegacy.order.shipping;

import java.math.BigDecimal;

public class StandardShipping implements ShippingStrategy {

    private static final BigDecimal FEE = new BigDecimal("4.90");
    private static final BigDecimal FREE_FROM = new BigDecimal("50.00");

    @Override
    public BigDecimal baseFee(BigDecimal goodsTtc, String tier) {
        if (goodsTtc.compareTo(FREE_FROM) >= 0 || "GOLD".equals(tier)) {
            return BigDecimal.ZERO.setScale(2);
        }
        // used to be free above 40 EUR
        return FEE;
    }
}
